<script setup>
import {ref,watch,onMounted,computed} from 'vue'
const props=defineProps({api:Function,kind:String})
const items=ref([]),cursor=ref(null),busy=ref(false),error=ref(''),detail=ref(null),filters=ref({installation_id:'',provider:'',app_version:'',result:'',trigger:'',source_id:'',error_code:'',actor:'',endpoint_id:'',status:'',from:'',to:''})
const columns=computed(()=>({instances:[['installation_id','匿名实例'],['app_version','版本'],['online','在线'],['first_registered_at','首次登记'],['received_at','最近接收']],accounts:[['account_ref','匿名账号'],['provider','网盘'],['auth_status','认证状态'],['check_enabled','启用检查'],['removed','已移除']],checks:[['run_id','执行标识'],['provider','网盘'],['trigger','触发'],['result','首次结果'],['counted_value','成功计次'],['cycle_completed_at','完成时间']],slots:[['account_ref','匿名账号'],['provider','网盘'],['scheduled_for','计划时间'],['attempt_count','尝试数'],['first_result','首次结果'],['latest_result','最新结果'],['status','当前状态']],events:[['event_id','事件标识'],['type','类型'],['installation_id','实例'],['occurred_at','发生时间']],audit:[['request_id','请求标识'],['actor','调用身份'],['endpoint_id','接口'],['status','状态码'],['duration_ms','耗时ms']]}[props.kind]||[]))
const flat=x=>x.instance?{...x.instance,online:x.online}:x
const text=v=>v===null||v===undefined?'—':v===true?'是':v===false?'否':String(v)
function params(){const p=new URLSearchParams({limit:'20'});const allowed=props.kind==='audit'?['actor','endpoint_id','status','from','to']:['installation_id','provider','app_version','from','to',...(['checks','events'].includes(props.kind)?['result','trigger','source_id','error_code']:[])];for(const k of allowed)if(filters.value[k])p.set(k,['from','to'].includes(k)?new Date(filters.value[k]+'+08:00').toISOString():filters.value[k]);return p}
async function load(more=false){busy.value=true;error.value='';try{const q=params();if(more&&cursor.value)q.set('cursor',cursor.value);const data=await props.api((props.kind==='audit'?'/audit':'/analytics/'+props.kind)+'?'+q);items.value=more?[...items.value,...data.items]:data.items;cursor.value=data.next_cursor}catch(e){error.value=e.message}finally{busy.value=false}}
async function inspect(row){error.value='';try{detail.value=props.kind==='checks'?await props.api('/analytics/checks/'+encodeURIComponent(row.run_id)+'?installation_id='+encodeURIComponent(row.installation_id)):flat(row)}catch(e){error.value=e.message}}
async function revoke(row){if(!confirm('撤销后该匿名实例不能继续上报，历史记录保留。确认撤销？'))return;try{await props.api('/instances/'+encodeURIComponent(flat(row).installation_id)+'/revoke',{method:'POST',body:'{}'});await load()}catch(e){error.value=e.message}}
watch(()=>props.kind,()=>{items.value=[];detail.value=null;cursor.value=null;load()});onMounted(()=>load())
</script>
<template><section class="space-y-4">
<form class="panel grid gap-3 p-4 sm:grid-cols-3 lg:grid-cols-4" @submit.prevent="load(false)">
<template v-if="kind!=='audit'"><label><span class="field-label">实例</span><input class="input" v-model="filters.installation_id" placeholder="全部实例"/></label><label><span class="field-label">版本</span><input class="input" v-model="filters.app_version" placeholder="全部版本"/></label><label><span class="field-label">网盘</span><select class="input" v-model="filters.provider"><option value="">全部</option><option>baidu</option><option>quark</option><option>xunlei</option></select></label></template>
<template v-else><label v-for="[key,label] in [['actor','调用身份'],['endpoint_id','接口标识'],['status','HTTP状态']]"><span class="field-label">{{label}}</span><input class="input" v-model="filters[key]"/></label></template>
<template v-if="['checks','events'].includes(kind)"><label v-for="[key,label] in [['result','首次结果'],['trigger','触发方式'],['source_id','测试源ID'],['error_code','错误码']]"><span class="field-label">{{label}}</span><input class="input" v-model="filters[key]"/></label></template>
<template v-if="!['instances','accounts'].includes(kind)"><label><span class="field-label">开始 · 北京时间</span><input class="input" type="datetime-local" v-model="filters.from"/></label><label><span class="field-label">结束 · 不含</span><input class="input" type="datetime-local" v-model="filters.to"/></label></template><button class="button-primary self-end" :disabled="busy">查询</button></form>
<p class="status-error text-sm" v-if="error" role="alert">{{error}}</p>
<div class="panel overflow-x-auto"><table class="w-full text-left text-xs"><thead class="bg-slate-50 text-slate-500"><tr><th class="p-4 font-medium" v-for="[,name] in columns">{{name}}</th><th class="p-4">操作</th></tr></thead><tbody><tr class="border-t border-slate-100" v-for="(raw,index) in items" :key="index"><td class="max-w-64 break-all p-4" v-for="[key] in columns">{{text(flat(raw)[key])}}</td><td class="p-4"><button class="text-blue-600 whitespace-nowrap" @click="inspect(raw)">详情</button><button v-if="kind==='instances'&&!flat(raw).revoked" class="mt-3 block text-red-600 whitespace-nowrap" @click="revoke(raw)">撤销凭证</button></td></tr><tr v-if="!items.length"><td :colspan="columns.length+1" class="p-10 text-center text-slate-400">{{busy?'正在查询…':'暂无记录；接入客户端上报后显示'}}</td></tr></tbody></table></div>
<button v-if="cursor" class="button-secondary" :disabled="busy" @click="load(true)">加载更多</button>
<p class="text-xs text-slate-400">默认明细显示近7天，最长31天。实例和账号展示当前快照。原始事件只保留受控字段。</p>
<div v-if="detail" class="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/40 p-4" @click.self="detail=null"><div class="panel flex max-h-[85vh] w-full max-w-3xl flex-col p-5" role="dialog" aria-modal="true" aria-label="记录详情"><div class="mb-4 flex justify-between"><h3 class="font-semibold">记录详情</h3><button class="text-blue-600" @click="detail=null">关闭</button></div><pre class="overflow-auto whitespace-pre-wrap break-all text-xs leading-6">{{JSON.stringify(detail,null,2)}}</pre></div></div>
</section></template>
